package site.kael.conversationcompiler.repository.settings;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import site.kael.conversationcompiler.domain.settings.KnowledgeCompileSettings; import java.time.Instant; import java.util.*;
@Repository public class JdbcKnowledgeSettingsRepository implements KnowledgeSettingsRepository { private final JdbcTemplate jdbc; public JdbcKnowledgeSettingsRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public Optional<KnowledgeCompileSettings> find(){var x=jdbc.query("SELECT s.*,p.name provider_name FROM knowledge_compile_settings s LEFT JOIN model_providers p ON p.id=s.provider_id WHERE s.id=1",(r,n)->new KnowledgeCompileSettings(r.getString("provider_id"),r.getString("provider_name"),r.getString("model_name"),r.getInt("interval_minutes"),r.getString("prompt"),r.getBoolean("enabled"),r.getString("updated_at")));return x.stream().findFirst();} public void save(String providerId,String model,int interval,String prompt,boolean enabled){String now=Instant.now().toString();jdbc.update("INSERT INTO knowledge_compile_settings(id,provider_id,model_name,interval_minutes,prompt,enabled,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET provider_id=excluded.provider_id,model_name=excluded.model_name,interval_minutes=excluded.interval_minutes,prompt=excluded.prompt,enabled=excluded.enabled,updated_at=excluded.updated_at",providerId,model,interval,prompt,enabled,now,now);}}
